+// Sites (kitchens). Every location belongs to one site and a batch is at the
+// site of its location. Items, suppliers, recipes and dishes are shared.
+import { AppError } from "../errors.js";
+
+/** The site of a request that does not name one. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The locations of a site. */
+export function locationsAt(store, site) {
+  return store.data.locations.filter((l) => l.site === site);
+}
+
+/** The batches of a site (a new array). */
+export function batchesAt(store, site) {
+  const here = new Set(locationsAt(store, site).map((l) => l.id));
+  return store.data.batches.filter((b) => here.has(b.location));
+}
